style.css:
body {
    margin: 0;
    height: 100vh;
    display: flex;
    justify-content: center;
    align-items: center;
    background-image: url('https://example.com/your-image.jpg'); /* Replace with your image URL */
    background-size: cover; /* Cover the entire viewport */
    background-position: center; /* Center the image */
    background-repeat: no-repeat; /* Prevent repeating the image */
    color: white; /* Text color */
    font-family: Arial, sans-serif; /* Font style */
    text-align: center; /* Center text */
}

h1 {
    font-size: 3rem; /* Heading size */
    text-shadow: 2px 2px 4px rgba(0, 0, 0, 0.7); /* Shadow effect for better readability */
}

p {
    font-size: 1.5rem; /* Paragraph size */
    margin-top: 20px; /* Spacing above the paragraph */
    text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.5); /* Shadow effect */
}
